    public function quotation()
    {
        if (isset($_GET["token"])) {
            $token = $_GET["token"];
            $action = $_GET["action"];
            $lead_id = encrypt_decrypt($token, 'decrypt');

            if ($lead_id) {
                $lead_det = $this->leads_model->md5_lead_details($lead_id);
                $action_id = encrypt_decrypt($action, 'decrypt');
                $payment_type = $this->mcommon->specific_row_value('lead_package_details', array('lead_id' => $lead_det['id']), 'payment_type');
                $link_active = $this->mcommon->specific_row_value('lead_action_log', array('id' => $action_id), 'link_active');
                $link_active = ($link_active === "0" || $link_active === 0) ? 'inactive' : 'active';

                if ((($lead_det["lead_status"] == 642 || $lead_det["lead_status"] == 643 || $lead_det["lead_status"] == 304) && $lead_det["lead_status"] != 306 && $link_active == 'active') || isset($this->auth_user_id)) {
                    $lead_id = $lead_det["id"];

                    if($payment_type != 'online' && $lead_det["lead_status"] == 643 && !isset($this->auth_user_id)){
                        return redirect("/payment/failure?title=Accepted%20!&desc=This quotation has been accepted and payment is processing..");
                    }

                    // $action_message = $this->mcommon->specific_row_value('lead_action_log', array('id' => $action_id), 'email_message');
                    $created_at = $this->mcommon->specific_row_value('lead_action_log', array('id' => $action_id), 'created_at');
                    // $createdTimestamp = new DateTime($created_at);
                    $updated_at = $this->mcommon->specific_row_value('lead_action_log', array('id' => $action_id), 'updated_at');

                    $createdTimestamp = new DateTime($updated_at);
                    $currentDateTime = new DateTime();
                    $diff = $currentDateTime->diff($createdTimestamp);
                    $totalDays = ($diff->y * 365) + ($diff->m * 30) + $diff->d;
                    $diffHours = ($totalDays * 24) + $diff->h;
                    if ($diffHours < 48 || isset($this->auth_user_id)) {
                        $OrderID = $action_id . "-OTLDPMET" . $lead_id;
                        $raw_salesorder = $action_id . "-OTLDPMET" . $lead_id;

                        if($link_active == "inactive"){
                            $details = $this->db->select("history_lead_package_details.*,count(history_lead_package_details.lead_package_detail_id) as qty,ontime_category_services_.service_name, lead_packages.package_name")
                            ->from("history_lead_package_details")
                            ->join("ontime_category_services_", "ontime_category_services_.service_id = history_lead_package_details.service_id")
                            ->join("lead_packages", "lead_packages.package_id = history_lead_package_details.package_id")
                            ->where("history_lead_package_details.lead_id", $lead_id)
                            ->where("history_lead_package_details.quotation_action_id", $action_id)
                            ->group_by("history_lead_package_details.service_id")->get()->result_array();
                        } else {
                            $details = $this->db->select("lead_package_details.*,count(lead_package_details.lead_package_detail_id) as qty,ontime_category_services_.service_name, lead_packages.package_name")
                            ->from("lead_package_details")
                            ->join("ontime_category_services_", "ontime_category_services_.service_id = lead_package_details.service_id")
                            ->join("lead_packages", "lead_packages.package_id = lead_package_details.package_id")
                            ->where("lead_package_details.lead_id", $lead_id)
                            ->group_by("lead_package_details.service_id")->get()->result_array();
                        }

                        $user_pos_id = $this->mcommon->specific_row_value('users', array('user_id' => $lead_det["lead_created_by"]), 'employee_id');
                        $user_email = $this->mcommon->specific_row_value('users', array('user_id' => $lead_det["lead_created_by"]), 'email');

                        $data = array(
                            'name' => $lead_det["customer_name"],
                            'email' => $lead_det["customer_email"],
                            'mobile' => $lead_det["customer_mobile"],
                            'subject' => 'OnTime Biz - Quotation - #' . $OrderID,
                            'lead_id' => $lead_id,
                            "lead" => $lead_det,
                            "reference" => $OrderID,
                            // "message" => $action_message,
                            "service" => $lead_det["category_code"] . " - " . $lead_det["service_name"],
                            "amount" => $link_active == "inactive" ? $details[0]["lead_amount"] : $lead_det["lead_amount"],
                            "admin_charges" => $lead_det["lead_admin_fee"],
                            "details" => $details,
                            "branch_id" => $lead_det["branch_id"],
                            "created_at" => $created_at,
                            //"last_updated_at" => $updated_at,
                            "action_id" => $action_id,
                            'link_active' => $link_active,
                            'payment_type' => $payment_type,
                            'user_pos_id' => $user_pos_id,
                            'user_email' => $user_email,
                        );

                        return $this->load->view('mails/quotation', $data);
                    } else {
                        // echo "The current date and time is NOT within 48 hours of the specific date and time.";
                        return redirect("/payment/failure?title=Expired%20!&desc=The Quotation link is expired. Please contact coordinator to make the quoation available.");
                    }
                } else {
                    return redirect("/payment/failure?title=Expired%20!&desc=This%20Quotation%20link%20is%20expired%20or%20Invalid1.");
                }
            } else {
                return redirect("/payment/failure?title=Expired%20!&desc=This%20Quotation%20link%20is%20expired%20or%20Invalid2.");
            }
        } else {
            return redirect("/payment/failure?title=Expired%20!&desc=This%20Quotation%20link%20is%20expired%20or%20Invalid3.");
        }
    }

    public function quotationCallback()
    {
        if (isset($_GET["token"]) && isset($_GET["action"])) {
            $token = $_GET["token"];
            $action = $_GET["action"];
            $ref = $_GET["ref"];
            $lead_id = encrypt_decrypt($token, 'decrypt');
            $action_id = encrypt_decrypt($ref, 'decrypt');
            $lead_det = $this->leads_model->lead_details($lead_id);
            $check_status = [623, 619];
            $payment_type = $this->mcommon->specific_row_value('lead_package_details', array('lead_id' => $lead_det['id']), 'payment_type');
            // var_dump($action_id);exit;

            if ($lead_det) {
                if (! in_array($lead_det["lead_status"], $check_status)) {
                    if ($_GET["action"] == "accept") {
                        if($lead_det["lead_status"] == 643){
                            $quotationlink = "/leads/lead/quotation?token=" . encrypt_decrypt(md5($lead_det["id"])) . "&action=" . encrypt_decrypt($action_id);
