                        }

                        if($payment_type == "cash"){
                            $action_amount = $this->mcommon->specific_row_value('lead_action_log', array('id' => $action_id), 'action_amount');
                            $customer_otp = $_GET["OTP"];
                            $log_insert_array = array('action_id' => 444, 'lead_id' => $lead_id, 'action_amount' => $action_amount, 'remarks' => "Quotation accepted by Customer", 'status_id' => 643);
                            $insert_log = $this->mcommon->common_insert('lead_action_log', $log_insert_array);
                            $this->mcommon->common_edit('leads', ["lead_status" => 643], array('id' => $lead_id));

