                        } else if($payment_type == "card"){
                            $action_amount = $this->mcommon->specific_row_value('lead_action_log', array('id' => $action_id), 'action_amount');

                            $log_insert_array = array('action_id' => 444, 'lead_id' => $lead_id, 'action_amount' => $action_amount, 'remarks' => "Quotation accepted by Customer", 'status_id' => 643);
                            $insert_log = $this->mcommon->common_insert('lead_action_log', $log_insert_array);
                            $this->mcommon->common_edit('leads', ["lead_status" => 643], array('id' => $lead_id));

                           return redirect("/payment/failure?title=Accepted%20!&desc=This quotation has been accepted and payment is processing.");

                            // $this->card_payment_internal($lead_id, $action_amount);
                            exit;
                        } else {
                            $log_insert_array = array('action_id' => 444, 'lead_id' => $lead_id, 'remarks' => "Quotation accepted by Customer", 'status_id' => 643);
                            $insert_log = $this->mcommon->common_insert('lead_action_log', $log_insert_array);
                            $this->mcommon->common_edit('leads', ["lead_status" => 643], array('id' => $lead_id));

                            $quotationlink = "/leads/lead/quotation?token=" . encrypt_decrypt(md5($lead_det["id"])) . "&action=" . encrypt_decrypt($action_id);
                            return redirect($quotationlink);
                        }

                    } elseif ($_GET["action"] == "paynow") {
                        // echo $action["payment_link"];

                        if ($_GET["ref"]) {
                            $payment_link = $this->mcommon->specific_row_value('lead_action_log', array('id' => $action_id), 'payment_link');
                            $amount_payment = $this->mcommon->specific_row_value('lead_action_log', array('id' => $action_id), 'action_amount');

                            // if(empty($payment_link)){
                                $customer_email = $lead_det["customer_email"];
                                $pre_token = trim($lead_id) . "-" . trim($customer_email) . "-@OnTimeCRM11..";

                                $token1 = md5($pre_token);
                                $token2 = md5(strrev($pre_token));
                                $token = $token1 . "-" . $token2;

                                $crypt_amount = encrypt_decrypt($amount_payment, 'encrypt');

                                $log_id = encrypt_decrypt($action_id);

                                $payment_link = "https://crm.ontimegroup.com/payment/ccpay?ref=" . $token . "&token=" . $crypt_amount . "&identity=" . $log_id;

