                        }
                        $package_id = $this->mcommon->specific_row_value('leads', array('id' => $lead_id), 'package_id');
                        if(!in_array($package_id, [199,204,205,258,259,260, 200,201,206,207,208,209,261,262,263, 222,223,224, 225,226,227, 228,229,230])){
                            $exist_lead_package_details = $this->mcommon->specific_fields_records_all('lead_package_details', array('lead_id' => $lead_id));
