                                }
                            }
                            
                            $delete_package_details = $this->mcommon->common_delete('lead_package_details', array('lead_id' => $lead_id));
                            $log_insert_array = array('action_id' => 450, 'lead_id' => $lead_id, 'remarks' => "Quotation Declined by Customer", 'status_id' => 649);
                            $insert_log = $this->mcommon->common_insert('lead_action_log', $log_insert_array);
                            $this->mcommon->common_edit('leads', ["lead_status" => 649], array('id' => $lead_id));
                        } else {
                            $sub_lead_id = $this->mcommon->specific_row_value('leads', array('lead_parent_id' => $lead_id), 'id');
                            $this->mcommon->common_edit('leads', ['block_category' => NULL, 'ins_status' => NULL, 'property_value' => NULL,'process_time' => NULL, 'estimated_date' => NULL], array('id' => $sub_lead_id));

                            $log_insert_array = array('action_id' => 450, 'lead_id' => $lead_id, 'remarks' => "Quotation Declined by Customer", 'status_id' => 649);
                            $insert_log = $this->mcommon->common_insert('lead_action_log', $log_insert_array);
                            $this->mcommon->common_edit('leads', ["lead_status" => 649], array('id' => $lead_id));
