    public function get_mercatobiz_details($lead_id)
    {
        $view_data['lead_id'] = $lead_id;
        $url = "https://crm.mercatobiz.com/api/v1/lead/fetch_biz_lead_details";
        $curl = curl_init();
        curl_setopt_array($curl, array(
            CURLOPT_URL => $url,
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_ENCODING => '',
            CURLOPT_MAXREDIRS => 10,
            CURLOPT_TIMEOUT => 0,
            CURLOPT_FOLLOWLOCATION => true,
            CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
            CURLOPT_CUSTOMREQUEST => 'POST',
            CURLOPT_POSTFIELDS => json_encode($view_data),
            CURLOPT_HTTPHEADER => array(
                'Content-Type: application/json',
                'Accept: application/json'
            ),
        ));
         $response = curl_exec($curl);
        curl_error($curl);
        $result = json_decode($response, true);
        
        $view_data['paid_amount'] = $result['paid_amount'];
        $view_data['lead_details'] = $result['lead_details'];
        $view_data['lead_customer'] = $result['lead_customer'];
        $view_data['lead_created_details'] = $result['lead_by_details'];
        $view_data['lead_assigned_details'] = $result['lead_assigned_to_details'] ?? $result['lead_assigned_by_details'];
        $view_data['lead_attachments'] = $result['lead_attachments'];       
        $view_data['timeline'] = $result['timeline'];
        $view_data['crm_created_details'] = $this->get_crm_user_display_data($lead_id, 'mercatobiz');

        $data = array(
            'page_title' => 'Deals',
            'title' => 'Deals',
            'content' => $this->load->view('leads/lead/view_biz', $view_data, TRUE),
        );
        $this->load->view('template/base_template_modal_v3', $data);
    }

    public function mercatobiznew($value = '')
    {
        //echo "bizinsert_lead2=connected<br>";

        //echo "<pre>";
        //print_r($value);
        if ($this->verify_min_level(1)) {
            $curl = curl_init();
            curl_setopt_array(
                $curl,
                array(
                    CURLOPT_URL => 'https://crm.mercatobiz.com/api/v1/lead/fetch_biz_business_activity',
                    CURLOPT_RETURNTRANSFER => true,
                    CURLOPT_ENCODING => '',
                    CURLOPT_MAXREDIRS => 10,
                    CURLOPT_TIMEOUT => 0,
                    CURLOPT_FOLLOWLOCATION => true,
                    CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
                    CURLOPT_CUSTOMREQUEST => 'GET',
                    CURLOPT_HTTPHEADER => array(
                        'Content-Type: application/json',
                    ),
                )
            );

            $response = curl_exec($curl);
            curl_close($curl);
            $biz_res = json_decode($response, true);

            // echo "bizinsert_lead2=verify_min_level<br>";
            if (isset($_POST['submit']) or !empty($value)) {
                //   echo "bizinsert_lead2=_POST_submit<br>";
                log_message('error', 'create lead');
                $branch_id = 107;
                $category_id = 109;
                $service_id = 1009;

                $lead_type = isset($value) && $value['new_lead_type'] != '' ? $value['new_lead_type'] : $this->input->post('lead_type');
                $lead_name =  isset($value) && $value['new_lead_name'] != '' ? $value['new_lead_name'] : $this->input->post('lead_name');
                $lead_contact = isset($value) && $value['new_lead_contact'] != '' ? $value['new_lead_contact'] : $this->input->post('lead_contact');
                $lead_email = isset($value) && $value['new_lead_email'] != '' ? $value['new_lead_email'] : $this->input->post('lead_email');
                $lead_email = trim($lead_email);
                $lead_remarks = isset($value) && $value['new_lead_remarks'] != '' ? $value['new_lead_remarks'] : $this->input->post('lead_remarks');
                $lead_country_code = isset($value) && $value['new_lead_country_code'] != '' ? $value['new_lead_country_code'] : $this->input->post('lead_country_code');
                $group_crm_lead_id = isset($value) && $value['group_crm_lead_id'] != '' ? $value['group_crm_lead_id'] : 'Biz Lead';
                $lead_location = isset($value) && $value['lead_location'] != '' ? $value['lead_location'] : $this->input->post('lead_location');
                $lead_assigned_to = isset($value) && $value['lead_assigned_to'] != '' ? $value['lead_assigned_to'] : $this->input->post('lead_assigned_to');

                $this->form_validation->set_rules('lead_name', 'Customer Name', 'required');
                $this->form_validation->set_rules('lead_contact', 'Contact Number', 'required');
                $this->form_validation->set_rules('lead_country_code', 'Country code cannot be null', 'required');
                $this->form_validation->set_rules('lead_remarks', 'Remarks', 'required');

                $view_bizcategory = (isset($biz_res['business_activities_entry_ar']) && !empty($biz_res['business_activities_entry_ar'])) ? $biz_res['business_activities_entry_ar'] : array();
                $vb = array();
                if (!empty($view_bizcategory)) {
                    foreach ($view_bizcategory as $bk) {
                        $vb[$bk['field_name']] = $this->input->post($bk['field_name']);
                    }
                }
                $checklist_form_data = json_encode($vb); 

                if ($this->form_validation->run() == true) {
                    $this->db->trans_start();
                    try {
                        $random_email_name = strtolower($this->random_strings(10));
                        $random_email = $random_email_name . '@ontimecustomer.com';
                        $lead_email = ($lead_email == '') ? $random_email : $lead_email;
                        $user_id = $this->customer_handle($lead_name, $lead_contact, $lead_email, $lead_country_code, null);
                        $created_group = $this->db->select("groups.group_name")->from("group_members")->join("groups", "groups.group_id=group_members.group_id")->where("group_members.user_id", $this->auth_user_id)->where("group_members.is_primary_group_id", 1)->get()->first_row();

                        if ($user_id != 0) {
                            $insert_lead_array = array(
                                'customer_id' => $user_id,
                                'branch_id' => $branch_id,
                                'category_id' => $category_id,
                                'service_id' => $service_id,
                                'group_crm_lead_id' => $group_crm_lead_id,
                                'lead_created_by' => $this->auth_user_id,
                                'lead_created_group' => $created_group->group_name,
                                'lead_added_on' => date('Y-m-d H:i:s'),
                                'contactable_date' => date('Y-m-d H:i:s'),
                                'lead_status' => 301,
                                'package_id' => 0,
                                'order_receipt' => 0,
                                'remarks' => $lead_remarks,
                                'is_assigned' => 0,
                                'lead_location' => $lead_location,
                                'lead_assigned_to' => $lead_assigned_to,
                            );
                            $insert_lead_id = $this->mcommon->common_insert('mercatobiz_leads', $insert_lead_array);
                            // print_r($insert_lead_id);
                            // print_r($this->db->error());
                            // exit();
                            $curl = curl_init();
                            $req = "lead_name=" . $lead_name . "&lead_email=" . $lead_email . "&lead_country_code=" . $lead_country_code . "&lead_contact=" . $lead_contact . "&lead_remarks=" . $lead_remarks . "&group_crm_lead_id=" . $group_crm_lead_id ."&lead_business_activity=" .$lead_business_activity ."&checklist_form_data=" . $checklist_form_data . "&lead_location=" . $lead_location . "&lead_assigned_to=" . $lead_assigned_to;
                            curl_setopt_array(
                                $curl,
                                array(
                                    CURLOPT_URL => "https://crm.mercatobiz.com/api/v1/lead/biz",
                                    CURLOPT_RETURNTRANSFER => true,
                                    CURLOPT_ENCODING => "",
                                    CURLOPT_MAXREDIRS => 10,
                                    CURLOPT_TIMEOUT => 30,
                                    CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
                                    CURLOPT_CUSTOMREQUEST => "POST",
                                    CURLOPT_POSTFIELDS => $req,
                                    CURLOPT_HTTPHEADER => array(
                                        "cache-control: no-cache",
                                        "content-type: application/x-www-form-urlencoded",
                                    ),
                                )
                            );

                            $response = curl_exec($curl);
                            log_message('debug', $req . "<br/>" . $response);
                            $err = curl_error($curl);

                            curl_close($curl);

                            $res = json_decode($response);

                            //  echo "bizinsert_lead2=success<br>";

                            $this->mcommon->common_edit('mercatobiz_leads', array('is_assigned' => 1, 'biz_lead_id' => $res->lead_id, 'lead_status' => 602), array('id' => $insert_lead_id));

                            $this->db->trans_commit();
                            $this->session->set_flashdata('alert', 'success');
                            $this->session->set_flashdata('alert_message', 'Lead has been created.');
                        } else {
                            $this->session->set_flashdata('alert', 'danger');
                            $this->session->set_flashdata('alert_message', 'Unable to create lead. There exist a problem in creating customer record. Please try again.');
                        }
                    } catch (Exception $e) {
                        $this->session->set_flashdata('alert', 'danger');
                        $this->session->set_flashdata('alert_message', 'Unable to create lead. There exist a problem in creating customer record. Please try again.');
                        $this->db->trans_rollback();
                    }
                } else {
                    $this->session->set_flashdata('alert', 'danger');
                    $this->session->set_flashdata('alert_message', validation_errors());
                }
                $this->db->trans_commit();
            }
            $view_data['nationality'] = $this->mcommon->specific_fields_records_all('nationalities', array('active' => 1));

            $view_data['branches'] = $this->mcommon->specific_fields_records_all('ontime_branches', array('is_active' => 1));
            $view_data['services'] = $this->leads_model->lead_services();
            $view_data['categories'] = $this->mcommon->specific_fields_records_all('ontime_categories', array('is_active' => 1));
            $view_data['packages'] = $this->mcommon->specific_fields_records_all('lead_packages', array('is_active' => 1));
            $view_data['bizcategory'] = (isset($biz_res['bizcategory']) && !empty($biz_res['bizcategory'])) ? $biz_res['bizcategory'] : array();
            $view_data['business_activities'] = (isset($biz_res['business_activities']) && !empty($biz_res['business_activities'])) ? $biz_res['business_activities'] : array();
            // $view_data['bizcategory'] = [];
            // $view_data['business_activities'] = [];

            $data = array(
                'page_title' => 'Mercato Biz Lead',
                'title' => 'Mercato Biz Lead',
                'content' => $this->load->view('leads/lead/mercatobiz_new', $view_data, true),
            );
            $this->load->view('template/base_template_v2', $data);
        } else {
            redirect('login');
        }
    }

