    public function do_upload($attachments)
    {
        $config['upload_path'] = FCPATH . 'uploads/email_doc';
        $config['allowed_types'] = 'gif|jpg|jpeg|png|xlsx|csv|doc|docx|ppt|pptx|pdf|txt';
        $config['max_size'] = 30000;    //  2048;
        $config['max_width'] = 2048;
        $config['max_height'] = 2048;

        // echo"<pre>";print_r($config);print_r($attachments);die;
        $this->load->library('upload', $config);

        $uploaded_files = array();
        for ($i = 0; $i < count($attachments['name']); $i++) {
            // for changing the name
            $filename = $attachments['name'][$i];
            $ext      = substr($filename,strrpos($filename,'.')+1);
            $fname    = date("dmYHis");
            $fname.=uniqid().".".$ext;

            $_FILES['userfile']['name'] = $fname;   //$attachments['name'][$i];
            $_FILES['userfile']['type'] = $attachments['type'][$i];
            $_FILES['userfile']['tmp_name'] = $attachments['tmp_name'][$i];
            $_FILES['userfile']['error'] = $attachments['error'][$i];
            $_FILES['userfile']['size'] = $attachments['size'][$i];

            if (!$this->upload->do_upload('userfile')) {
                $error = array('error' => $this->upload->display_errors());
                echo json_encode($error);
                return;
            } else {
                $data = array(
                    'file_name' => $this->upload->data('file_name'),
                    'file_path' => $this->upload->data('full_path'),
                    'file_type' => $this->upload->data('file_type'),
                    'file_size' => $this->upload->data('file_size'),
                    'view_path' => 'uploads/email_doc/' . $this->upload->data('file_name'),
                );
                $this->db->insert('email_attachments', $data);
                $uploaded_files[] = $data;
                // $uploaded_files[] = $this->upload->data();
            }
        }

        // Return the uploaded file details as JSON
        // echo json_encode($uploaded_files);
        return $uploaded_files;
    }

    /**
     * [action_email Lead followup through email]
     * @param  [type] $lead_id [lead's id]
     * @return [type]          [sends an email using SMTP and updates the action log]
     */
    public function action_email($lead_id)
    {
        if ($this->verify_min_level(1)) {
            if (isset($_POST['action_email'])) {
                $from_email = $this->input->post('from_email');
                $customer_email = $this->input->post('customer_email');
                $agent_email = $this->input->post('agent_email');
                $email_subject = $this->input->post('email_subject');
                $email_message = $this->input->post('email_message');
                $email_remarks = $this->input->post('email_remarks');
                $contactable_date = $this->input->post('contactable_date');

                // Attachments
                $attachments = $_FILES['email_attachments'];
                if (!empty($attachments)) {
                    $image_data = $this->do_upload($attachments);
                    $att = '';
                    if (!empty($image_data)) {
                        foreach ($image_data as $ik => $im) {
                            if ($im['view_path'] != null) {
                                $att .= '<a href="' . base_url() . $im['view_path'] . '" download>' . $im['file_name'] . '</a><br/>';
                            }
                        }
                    }
                }  

                //construct message
                // $customer_name = $this->mcommon->specific_row_value('lead_users', array('email' => $customer_email), 'first_name');
                $customer_id = $this->mcommon->specific_row_value('leads', array('id' => $lead_id), 'customer_id');
                $customer_name = $this->mcommon->specific_row_value('lead_users', array('user_id' => $customer_id), 'first_name');
                $agent_name = $this->mcommon->specific_row_value('users', array('email' => $agent_email), 'first_name');
                $applicant_name = $this->mcommon->specific_row_value('leads', array('id' => $lead_id), 'applicant_name');
                $is_corporate = $this->mcommon->specific_row_value('leads', array('id' => $lead_id), 'is_corporate');
                if($applicant_name != '' && $applicant_name != null){
                    $customer_name = $applicant_name;
                }
                $message = "Dear " . $customer_name . ",<br /><br />";
                $message .= $email_message;
                if (!empty($attachments)) {
                    if ($att != '') {
                        $message .= "<p><strong>Attachments<strong/></p>" . "<br />";
                        $message .= $att . "<br /><br />";
                    }
                } 
                $message .= "<br/><br/>";
                // $message .= "Sincerly,<br /><br />" . $agent_name . "<br />ONTIME GROUP";

                // print_r($_POST);
                if ($from_email != '' && $customer_email != '' && $agent_email != '' && $email_subject != '' && $email_message != '') {
                    //SEND EMAIL TO CUSTOMER

                    $lead_branch_id = $this->mcommon->specific_row_value('leads', array('id' => $lead_id), 'branch_id');
                    $auth_user_group_id = $this->mcommon->specific_row_value('group_members', array('user_id' => $this->auth_user_id, 'is_primary_group_id' => 1), 'group_id');
                    if(!empty($auth_user_group_id) && $auth_user_group_id != null && $auth_user_group_id == '74'){
                        $lead_branch_id = 106;
                    }

                    $bcc_usermail = [];
                    array_push($bcc_usermail, ["email" => "crm@ontimegroup.com", "name" => "CRM"]);

                    $cc = [["name" => "GoldenCube", "email" => "team@goldencube.ae"]];
                        if($is_corporate == 'Corporate'){
                            $cc = [["email"=>'Corporate@goldencube.ae']];
                        }

                    $email_array = array(
                        'email' => $customer_email,
                        'subject' => $email_subject,
                        'template' => $lead_branch_id == '106' ? 'mails/gc_template' : 'mails/lead_template',
                        'from_name' => $this->auth_first_name,
                        'from_email' => $this->auth_email,
                        'message' => $message,
                        'reply_to' => $this->auth_email,
                        'cc' => $lead_branch_id == '106' ? $cc : 
                            [["email" => $this->auth_email]],
                        'bcc' => $bcc_usermail,
                        'branch_id' => $lead_branch_id,
                    );
                    //print_r($email_array);
                    $send_mail = send_lead_template_email($email_array);
                    // exit();

                    log_message('error', $send_mail);
                    if ($send_mail) {
                        //add entry in lead action log
                        $log_insert_array = array('action_id' => 404, 'lead_id' => $lead_id, 'action_on' => date('Y-m-d H:i:s'), 'remarks' => 'Sent an email to ' . $customer_email . '. <br /><br /><strong>Remarks:</strong>' . $email_remarks . '<br /><br />Email Message as follow as<br /><br /><pre>' . $message . '</pre>', 'action_by' => $this->auth_user_id, 'status_id' => 304);
                        $insert_log = $this->mcommon->common_insert('lead_action_log', $log_insert_array);
                        if ($insert_log > 0) {
                            //update lead status and contactable date in lead table
                            $update_lead_array = array('lead_status' => 304, 'contactable_date' => $contactable_date);
                            $update_lead = $this->mcommon->common_edit('leads', $update_lead_array, array('id' => $lead_id));
                            $this->session->set_flashdata('alert', 'success');
                            $this->session->set_flashdata('alert_message', 'Email sent successfully. You will receive the copy of email.');
                        } else {
                            $this->session->set_flashdata('alert', 'danger');
                            $this->session->set_flashdata('alert_message', 'Email sent successfully. But unable to update the lead record. Contact support.');
                        }
                    } else {
                        $this->session->set_flashdata('alert', 'danger');
                        $this->session->set_flashdata('alert_message', 'Unable to send email at this moment.Please try again.');
                    }

                    redirect('leads/lead/view/' . $lead_id);
                } else {
                    $this->session->set_flashdata('alert', 'danger');
                    $this->session->set_flashdata('alert_message', 'Unable to send email at this moment.Please try again.');
                }
            }
        } else {
            redirect('login');
        }
    }

    public function action_uploadattachments($lead_id)
    {
        if (!$this->verify_min_level(1)) {
            return redirect('login');
        }

        if (!isset($_POST['action_uploadattachments'])) {
            return redirect('leads/lead/view/' . $lead_id);
        }

        if (!isset($_FILES['attachments_lead']) || count($_FILES['attachments_lead']['name']) == 0) {
            $this->session->set_flashdata('alert', 'danger');
            $this->session->set_flashdata('alert_message', 'No attachments found to upload.');
            return redirect('leads/lead/view/' . $lead_id);
        }

        $this->load->library('upload');
        $this->load->library('zip');

        $upload_path = 'uploads/leads/';
        if (!is_dir($upload_path)) {
            mkdir($upload_path, 0777, true);
        }

        $files = $_FILES['attachments_lead'];
        $countfiles = count($files['name']);
        $uploaded_files = [];

        for ($i = 0; $i < $countfiles; $i++) {
            if (!empty($files['name'][$i])) {
                $_FILES['file']['name']     = $files['name'][$i];
                $_FILES['file']['type']     = $files['type'][$i];
                $_FILES['file']['tmp_name'] = $files['tmp_name'][$i];
                $_FILES['file']['error']    = $files['error'][$i];
                $_FILES['file']['size']     = $files['size'][$i];

                $config['upload_path']   = $upload_path;
                $config['allowed_types'] = 'jpg|jpeg|png|gif|pdf';
                $config['max_size']      = '30000';
                $config['file_name']     = pathinfo($files['name'][$i], PATHINFO_FILENAME) . '_' . time();

                $this->upload->initialize($config);

                if ($this->upload->do_upload('file')) {
                    $uploadData = $this->upload->data();
                    $filename = $uploadData['file_name'];

                    $uploaded_files[] = [
                        'name' => $files['name'][$i],
                        'path' => $upload_path . $filename
                    ];
                }
            }
        }

        // Insert uploaded files
        if (count($uploaded_files) > 1) {
            // Create ZIP file
            $zip_filename = 'attachments_' . $lead_id . '_' . time() . '.zip';
            $zip_path = $upload_path . $zip_filename;

            foreach ($uploaded_files as $file) {
                $this->zip->read_file($file['path']);
            }

            $this->zip->archive($zip_path);

            $insert_attachment_array = [
                'lead_id'         => $lead_id,
                'attachment_name' => 'Multiple Attachments',
                'attachment_url'  => base_url($zip_path)
            ];
            $this->mcommon->common_insert('lead_attachments', $insert_attachment_array);

            // Optionally delete individual files
            foreach ($uploaded_files as $file) {
                unlink($file['path']);
            }
        } elseif (count($uploaded_files) === 1) {
            $file = $uploaded_files[0];
            $insert_attachment_array = [
                'lead_id'         => $lead_id,
                'attachment_name' => $file['name'],
                'attachment_url'  => base_url($file['path'])
            ];
            $this->mcommon->common_insert('lead_attachments', $insert_attachment_array);
        }

        $this->session->set_flashdata('alert', 'success');
        $this->session->set_flashdata('alert_message', 'Attachment(s) uploaded successfully.');
        redirect('leads/lead/view/' . $lead_id);
    }

