    public function send_reply($request_id,$lead_id){
        if ($this->verify_min_level(1)) {
            if (isset($_POST['reply_btn'])) {
                $this->form_validation->set_rules('to_mail', 'To', 'required');
                // $this->form_validation->set_rules('cc_mail', 'cc', 'required');
                $this->form_validation->set_rules('subject', 'Subject', 'required');
                $this->form_validation->set_rules('email_message', 'Email body', 'trim|required');
                if ($this->form_validation->run() == true) {
                    $to_mail = $this->input->post('to_mail');
                    $cc_mail = $this->input->post('cc_mail');
                    $email_subject = $this->input->post('subject');
                    $email_message = $this->input->post('email_message');

                    // Attachments
                    $attachments = $_FILES['conv_email_attachments'];
                    if (!empty($attachments)) {
                        $image_data = $this->do_upload($attachments);
                        $att = '';
                        if (!empty($image_data)) {
                            foreach ($image_data as $ik => $im) {
                                if ($im['view_path'] != null) {
                                    $att .= '<a href="' . base_url() . $im['view_path'] . '" download>' . $im['file_name'] . '</a><br/>';
                                }
                            }
                        }
                    }
                    if (!empty($attachments)) {
                        if ($att != '') {
                            $email_message .= "<p><strong>Attachments<strong/></p>" . "<br />";
                            $email_message .= $att . "<br /><br />";
                        }
                    }

                    $cc_usermail = [];
                    array_push($cc_usermail, ["email" => $cc_mail]);

                    $bcc_usermail = [];
                    array_push($bcc_usermail, ["email" => "crm@ontimegroup.com", "name" => "CRM"]);

                    $branch_id = $this->mcommon->specific_row_value('leads', array('id' => $lead_id), 'branch_id');

                    if(!empty($cc_mail)){
                        $email_array = array(
                            'email' => $to_mail,
                            'subject' => $email_subject,
                            'template' => 'mails/blank_template',
                            'message' => $email_message,
                            'cc' => $cc_usermail,
                            "bcc" => $bcc_usermail,
                            'branch_id' => $branch_id,
                        );
                    } else {
                        $email_array = array(
                            'email' => $to_mail,
                            'subject' => $email_subject,
                            'template' => 'mails/blank_template',
                            'message' => $email_message,
                            "bcc" => $bcc_usermail,
                            'branch_id' => $branch_id,
                        );
                    }

                    $send_mail = send_lead_template_email($email_array);

