                    $insert_log = $this->mcommon->common_insert('lead_action_log', $log_insert_array);
                    
                    $assigned_to = $this->mcommon->specific_row_value('leads_assigned', array('lead_id' => $lead_id), 'assigned_to');
                    $assigned_to_email = $this->mcommon->specific_row_value('users', array('user_id' => $assigned_to), 'email');
                    $assigned_to_name = $this->mcommon->specific_row_value('users', array('user_id' => $assigned_to), 'first_name');
                    $subject = "Ontiem CRM ALERT - Customer Replied Your Email";

                    $message = "Dear " . $assigned_to_name . ",<br/>
                    <br/>Customer is Replied your mail. <br/>
                    <br/>Please login into CRM and go to https://crm.ontimegroup.com/leads/lead/view/" . $lead_id . " .";

                    $email_array = array(
                        'email' => $assigned_to_email,
                        'subject' => $subject,
                        'template' => 'mails/lead_template',
                        'from_name' => "ONTIME CRM ALERT",
                        'message' => $message,
                        'branch_id' => $branch_id,
                    );
                    $send_mail = send_lead_template_email($email_array);

                    // log_message('error', $send_mail);
                    $this->session->set_flashdata('alert_reply', 'success');
                    $this->session->set_flashdata('alert_message', 'Reply sent successfully.');
                } else {
                    $this->session->set_flashdata('alert_reply', 'danger');
                    $this->session->set_flashdata('alert_message', validation_errors());
                }
            }
            redirect('leads/lead/view/' . $lead_id);
        }
    }

    public function download_attachment($content_url = null){
        $content_url = $content_url ?: $this->input->get('content_url');
        $content_type = $this->input->get('content_type');
        $image_name = $this->input->get('image_name');
        if(!empty($content_url)){
            $url = 'https://94.200.55.118:5000'.$content_url;   //.'/'.$image_name;
            $api_key = '171016F2-9943-418C-AD51-56E7E7C7DF4E';
            $headers = [
                "authtoken: $api_key"
            ];
        
            $ch = curl_init();
            // Set the cURL options
            curl_setopt($ch, CURLOPT_URL, $url); // Use the URL with query parameters
            curl_setopt($ch, CURLOPT_RETURNTRANSFER, true); // Return response as a string
            curl_setopt($ch, CURLOPT_HTTPHEADER, $headers); // Set the headers
            curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, 0);
            curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false); // Disable SSL verification (like verify=False in requests)
            
            $response = curl_exec($ch);
            $http_code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
            // $content_type = curl_getinfo($ch, CURLINFO_CONTENT_TYPE);
            if(curl_errno($ch)) {
                // Handle error (e.g., display an error message)
                echo 'Error: ' . curl_error($ch);
            } else {
                // Set headers to prompt the file download in the browser
                header('Content-Type: application/octet-stream'); // Content type (change based on your file type)
                header('Content-Disposition: attachment; filename="attachment.pdf"'); // File name in download prompt
                header('Content-Length: ' . strlen($response)); // Length of the file to be downloaded
                
                // Output the content directly to the browser for download
                echo $response;
            }
            curl_close($ch);
        }
    }

    public function hashPasswordUsingSHA256(string $data): string
    {
        return base64_encode(hash('sha256', $data, true));
    }

    public function card_payment_internal($lead_id = null, $amount = null, $sub_lead_id = null)
    {

        if ($this->verify_min_level(1)) {

            $amount = $amount;
            $lead_id = $lead_id;
            if (!$amount && !$lead_id) {
                $postData = json_decode(file_get_contents("php://input"), true);
                $lead_id = isset($postData['lead_id']) ? $postData['lead_id'] : null;
                $unique_id = isset($postData['unique_id']) ? $postData['unique_id'] : null;
                $amount = isset($postData['amount']) ? $postData['amount'] : null;
                $Quo_Number = isset($postData['quo_num']) ? $postData['quo_num'] : 0;
                if (!$unique_id) {
                    http_response_code(400);
                    echo json_encode(['error' => 'Unique ID is required']);
                    return;
                }
                if (!$lead_id) {
                    http_response_code(400);
                    echo json_encode(['error' => 'Lead_id is required']);
                    return;
                }
                if (!$amount) {
                    $amount = $this->mcommon->specific_row_value('lead_action_log', array('lead_id' => $lead_id, 'payment_ref' => $unique_id, 'action_id' => 442, 'status_id' => 641), 'action_amount');
                    if (!$amount) {
                        http_response_code(400);
                        echo json_encode(['error' => 'Amount is required']);
                        return;
                    }
                } else {
                    $unique_id = null;
                }
            }
            // Ensure amount is provided
            if (!$amount) {
                http_response_code(400);
                echo json_encode(['error' => 'Amount is required']);
                return;
            }
            if (!$lead_id) {
                http_response_code(400);
                echo json_encode(['error' => 'Lead_id is required']);
                return;
            }


            $employee_id = $this->mcommon->specific_row_value('users', array('user_id' => $this->auth_user_id), 'employee_id');
            $encrypt_emp_id = $this->hashPasswordUsingSHA256($employee_id);
            $card_leaddetails = $this->leads_model->card_leaddetails($lead_id);
            $timestamp = microtime(true); // Current time in microseconds
            $random_value = bin2hex(random_bytes(8));
            $current_timestamp = date('Y-m-d H:i:s');
            $pre_token = $lead_id . "-" . $amount . "-" . $employee_id . "-" . $timestamp . "-" . $random_value;
            $token1 = md5($pre_token);
            $token2 = md5(strrev($pre_token));
            $token = $token1 . "-" . $token2;

            $final_unique_id = !empty($unique_id) ? $unique_id : $token;

            $mobilePattern = '/^(?:\+971|00971|971|0)?(\d{7,8})$/';
            $landlinePattern = '/^(?:\+971|00971|971|0)?(\d{7})$/';
            $internationalPattern = '/^\+(\d{1,3})[\s-]?(\d+[\s-]?[\d\s-]*)$/';


            $mobile_no = '';

            if (preg_match($mobilePattern, $card_leaddetails["customer_mobile"], $matches)) {
                $mobile_no = $matches[1];
            } elseif (preg_match($landlinePattern, $card_leaddetails["customer_mobile"], $matches)) {
                $mobile_no = $matches[1];
            } elseif (preg_match($internationalPattern, $card_leaddetails["customer_mobile"], $matches)) {
                $mobile_no = $matches[2];
            } else {
                $mobile_no = $card_leaddetails["customer_mobile"];
            }

            $currentTime = strtotime($current_timestamp);
            $employee_id = $this->mcommon->specific_row_value('users', array('user_id' => $this->auth_user_id), 'employee_id');
            // $existingLog = $this->db->select("payment_ref, action_on") ->from("lead_action_log")->where("lead_id", $lead_id) ->where("action_id", 442)->order_by("action_on", "DESC")->get()->row();

            // $Quo_Number = $this->mcommon->specific_row_value('trn_quotationheader', array('main_lead_id' => $lead_id), 'DocNumb');
            // if (!empty($Quo_Number)) {
            //     $Quo_Number = $Quo_Number;
            // } else {
            //     $Quo_Number = 0;
            // }
            // Prepare the data for the cURL request
            $postData = [
                'UniqueID' =>  $final_unique_id,
                'UsrKey' => $employee_id,
                'Cust_Name' => $card_leaddetails['customer_name'],
                'Cust_Mobile' => $card_leaddetails['customer_country_code'] . $mobile_no,
                'Cust_Email' => $card_leaddetails['customer_email'],
                'Cust_Key' => $card_leaddetails['pos_cust_key'] ? $card_leaddetails['pos_cust_key'] : 0,
                'ActAmt' => round(floatval($amount), 2),
                'lead_id' => $card_leaddetails['lead_id'],
                'Quo_Number' => $Quo_Number
            ];

            if($sub_lead_id == null){
                $lead_det = $this->leads_model->lead_details($lead_id);
                $lead_created_by = $this->mcommon->specific_row_value('leads', array('id' => $lead_id), 'lead_created_by');
                $created_by_user = $this->mcommon->specific_row_value('users', array('user_id' => $lead_created_by), 'email');
                $created_by_user_emp_id = $this->mcommon->specific_row_value('users', array('user_id' => $lead_created_by), 'employee_id');

                if(!empty($lead_det["lead_zoho_id"])){
                    $lead_created_by = $this->mcommon->specific_row_value('leads', array('id' => $lead_id), 'lead_zoho_created_by_id');
                    if(!empty($lead_created_by)){
                        $created_by_user = $this->mcommon->specific_row_value('users', array('user_id' => $lead_created_by), 'email');
                        $created_by_user_emp_id = $this->mcommon->specific_row_value('users', array('user_id' => $lead_created_by), 'employee_id');
                    } else {
                        $created_by_user = '';
                    }

                    $postData["CampaignSource"] = $lead_det["lead_ad_campaign"];
                    $postData["ZohoLeadSource"] = $lead_det["lead_source"];
                    $postData["CampaignId"] = $lead_det["lead_ad_campaign_id"];
                    $postData["ZohoLeadId"] = $lead_det["lead_zoho_id"];
                    $postData["LeadFrom"] = ['Zoho'];
                    $postData["ZohoCreatedBy"] = $created_by_user_emp_id ? $created_by_user . ' (' . $created_by_user_emp_id . ')' : $created_by_user;
                } else {
                    $postData["LeadSource"] = 'Website';
                    $postData["LeadFrom"] = $lead_det["lead_from"];
                    $postData["CRMLeadId"] = $lead_id;
                    $postData["ZohoCreatedBy"] = $created_by_user;
                    $postData["LeadCreatedBy"] = $created_by_user_emp_id ? $created_by_user . ' (' . $created_by_user_emp_id . ')' : $created_by_user;
                }
                $postData["MainServiceId"] = $lead_det['main_service_type'];
            }

            if($sub_lead_id != null && !empty($sub_lead_id)){
                $getsub_service_id = $this->mcommon->specific_row_value('leads', array('id' => $sub_lead_id), 'main_service_type');
                $postData["MainServiceId"] = $getsub_service_id;
            }

            $emp = $this->db->select("*")->from("users")->where("user_id", $this->auth_user_id)->get()->first_row();
            $employee = $emp->first_name . " " . $emp->last_name . "(" . $emp->employee_id . ")";
            $log_insert_array = array('action_id' => 442, 'action_amount' => $amount, "payment_ref" => $token, "pg_req" => json_encode($postData), 'lead_id' => $lead_id, 'action_on' => $current_timestamp, 'remarks' => 'Card Payment Amount : ' . $amount . 'AED and Employee : ' . $employee, 'action_by' => $this->auth_user_id, 'status_id' => 641);
            if (!empty($unique_id)) {
                $insert_log = $this->mcommon->specific_row_value('lead_action_log', array('lead_id' => $lead_id, 'action_id' => 442, 'status_id' => 641, 'payment_ref' => $unique_id), 'id');
                $update_array = array("pg_req" => json_encode($postData));
                $update_lead = $this->mcommon->common_edit('lead_action_log', $update_array, array('id' => $insert_log));
            } else {
                $insert_log = $this->mcommon->common_insert('lead_action_log', $log_insert_array);
            }
            $action_id = $insert_log;

            $postData["OrderRef"] = $action_id . '-OTLDPMET' . $lead_id;

            // $mes_data = json_encode($postData);
            // $email_array = array(
            //     'email' => 'gowtham.sk@mitrahsoft.com',
            //     'subject' => 'test',
            //     'template' => 'mails/template',
            //     'from_name' => "CRM ALERT",
            //     'message' => $mes_data,
            // );
            // $send_mail = send_template_email($email_array);

            $curl = curl_init();

            curl_setopt_array(
                $curl,
                array(
                    // CURLOPT_URL => 'https://paymentintegration.egovllc.com/Payment/CRMCardPayment',
                    CURLOPT_URL => 'https://ontimesmartpos.net/Payment/CRMCardPayment',
                    CURLOPT_RETURNTRANSFER => true,
                    CURLOPT_ENCODING => '',
                    CURLOPT_MAXREDIRS => 10,
                    CURLOPT_TIMEOUT => 0,
                    CURLOPT_FOLLOWLOCATION => true,
                    CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
                    CURLOPT_CUSTOMREQUEST => 'POST',
                    CURLOPT_POSTFIELDS => json_encode($postData),
                    CURLOPT_HTTPHEADER => array(
                        'Content-Type: application/json',
                        'Authorization: ' . $encrypt_emp_id
                    )
                )
            );

            $response = curl_exec($curl);

            if (curl_errno($curl)) {
                $response = json_encode($postData) . "<br>" . curl_error($curl);
                // print_r(curl_error($curl));
                curl_close($curl);
            } else {
                $response = $response;
                curl_close($curl);
            }
            // Check for cURL errors or unsuccessful response
            if ($response === false) {
                // http_response_code($httpCode);
                echo json_encode(['error' => 'Failed to connect to external API']);
                return;
            }

            // Send the external API's response back to the frontend
            echo $response;
        } else {
            redirect('login');
        }
    }

