    }

    public function get_b2b_assigned_users()
    {
        $url = 'https://crm.ontimebiz.com/api/v1/lead/fetch_assigned_to_users';
        $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, $url); 
        curl_setopt($ch, CURLOPT_HTTPHEADER, [
            'Accept: application/json',
            'Content-Type: application/json'
        ]);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true); 
        curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, 0);
        curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false);
        
        $response = curl_exec($ch);
        curl_close($ch);
        
        // Decode the JSON response
        $users = json_decode($response, true);

        $location = $this->input->post('location');
        $normalized_location = strtolower(str_replace(' ', '_', trim($location)));

        // $filtered_users = array_filter($users, function($user) use ($location) {
        //     return strtolower(trim($user['location'])) === strtolower(trim($location));
        // });
        $filtered_users = array_filter($users, function($user) use ($normalized_location) {
            $user_location = strtolower(str_replace(' ', '_', trim($user['location'])));
            return $user_location === $normalized_location;
        });

        // Reindex array
        $filtered_users = array_values($filtered_users);

        // Return as JSON
        echo json_encode($filtered_users);
        exit;
    }

    public function dhiram_check()
    {
        if (!empty($_FILES["file"]["tmp_name"])) {
            $file_tmp = $_FILES["file"]["tmp_name"];
            $score = 0;
            $totalChecks = 5;

            $type = $_FILES["file"]["type"];
            if(!strpos($type, 'pdf'))
            {
                echo json_encode([
                    "status_code" => 400,
                    "success" => false,
                    "message" => "Upload valid PDF",
                    "amount" => null,
                    "contains_images" => null,
                    "image_resolutions" => null
                ]);
                exit;
            }

            $fileSizeMB = round(filesize($file_tmp) / 1048576, 2);
            if ($fileSizeMB < 10) {
                $score += 1;
            }

            $parser = new Parser();  
            $pdf = $parser->parseFile($file_tmp);
            $text = $pdf->getText();
            $pdfText = mb_convert_encoding($text, 'UTF-8', 'Windows-1256');
            $goodpdf = 0;   
            if (!empty($text) && (preg_match('/Title Deed/i', $text))) 
            {
                $score += 2;
                $goodpdf = 1;
            }

            preg_match('/([\d,]+)\s*Dirham/i', $text, $matches);
            $amount = !empty($matches[1]) ? $matches[1] . " Dirham" : null;
            $message = $amount ? "Amount found successfully." : "The word 'Dirham' was not found in the file.";

            $image_check_command = "pdfimages -list " . escapeshellarg($file_tmp) . " 2>&1";
            $output = shell_exec($image_check_command);

            $contains_images = false;
            $image_resolutions = [];
            $good_quality = true;
            $good_image = true;

            $min_width = 300;
            $min_height = 300;

            $color_map = ["0" => "Grayscale", "1" => "RGB", "2" => "CMYK", "3" => "Indexed", "4" => "Monochrome"];
            if ($output) 
            {
                $lines = explode("\n", trim($output));
                array_shift($lines);

                foreach ($lines as $line) {
                    $columns = preg_split('/\s+/', trim($line));

                    if (count($columns) >= 5 && is_numeric($columns[3]) && is_numeric($columns[4])) {
                        $contains_images = true;
                        $width = (int) $columns[3];
                        $height = (int) $columns[4];
                        $color_code = $columns[1];
                        $color_space = $color_map[$color_code] ?? "Unknown";

                        if ($width < $min_width || $height < $min_height) {
                            $good_quality = false;
                        }else{
                            $good_quality = true;
                        }

                        if ($color_space === "Grayscale" || $color_space === "Monochrome") {
                            $good_image = false;
                        }else{
                            $good_image = true;
                        }

                        $image_resolutions[] = [
                            "width" => $width,
                            "height" => $height,
                            "color_space" => $color_space,
                            "good_quality"  => $good_quality,
                            "good_image" => $good_image
                        ];
                    }
                }
            }
            if ($contains_images) 
            {
                if ($good_quality) {
                    $score += 1;
                }
                if ($good_image) {
                    $score += 1;
                }
                if($goodpdf != 1){
                    $score = 1;
                }
            }else{
                if($goodpdf != 0){
                    $score = 3;
                }
            }

            if ($score >= 4) {
                $qualityMessage = "Conclusion: PDF is of Good Quality!";
            } elseif ($score >= 2.5) {
                $qualityMessage = "Conclusion: PDF is Acceptable, but some improvements are needed.";
            } else {
                $qualityMessage = "Conclusion: PDF is Poor Quality! Consider regenerating it.";
            }

            echo json_encode([
                "status_code" => 200,
                "success" => true,
                "message" => $message,
                "amount" => $amount,
                "score" => $score,
                "qualityMessage" => $qualityMessage,
                "contains_images" => $contains_images,
                "image_resolutions" => $image_resolutions
            ]);
        } else {
            echo json_encode([
                "status_code" => 400,
                "success" => false,
                "message" => "Upload valid PDF",
                "amount" => null,
                "contains_images" => null,
                "image_resolutions" => null
            ]);
        }
    }

