                }else if(!empty($text) && (preg_match('/INITIAL CONTRACT OF SALE/i', $text)))
                {
                    $score += 2;
                    $goodpdf = 1;
                    $check = '/(\d[\d,\.]*)\s*AED\s*\n\s*Built Up Area/i';
                }
                $page_data = [];
                if(count($pdf->getPages()) > 1)
                {
                    foreach ($pages as $key => $page) {
                        $text = $page->getText();
                        $page_number = $key+1;
                        preg_match($check, $text, $matches);
                        $result = !empty($matches[1]) ? $matches[1] . " Dirham" : null;
                        $amount[$page_number] = $result;
                        $message[] = $result[$key] ? "Amount found in the " .$page_number." page" : "The word 'Dirham' is not found in the " .$page_number." page";
                    }
                }else{
                    preg_match($check, $text, $matches);
                    $amount[1] = !empty($matches[1]) ? $matches[1] . " Dirham" : null;
                    $message = $amount ? "Amount found successfully." : "The word 'Dirham' was not found in the file.";                   
                }
               
                $image_check_command = "pdfimages -list " . escapeshellarg($file_tmp) . " 2>&1";
                $output = shell_exec($image_check_command);

                $contains_images = false;
                $image_resolutions = [];
                $good_quality = true;
                $good_image = true;

                $min_width = 300;
                $min_height = 300;

                $color_map = ["0" => "Grayscale", "1" => "RGB", "2" => "CMYK", "3" => "Indexed", "4" => "Monochrome"];
                if ($output) 
                {
                    $lines = explode("\n", trim($output));
                    array_shift($lines);

                    foreach ($lines as $line) {
                        $columns = preg_split('/\s+/', trim($line));

                        if (count($columns) >= 5 && is_numeric($columns[3]) && is_numeric($columns[4])) {
                            $contains_images = true;
                            $width = (int) $columns[3];
                            $height = (int) $columns[4];
                            $color_code = $columns[1];
                            $color_space = $color_map[$color_code] ?? "Unknown";

                            if ($width < $min_width || $height < $min_height) {
                                $good_quality = false;
                            }else{
                                $good_quality = true;
                            }

                            if ($color_space === "Grayscale" || $color_space === "Monochrome") {
                                $good_image = false;
                            }else{
                                $good_image = true;
                            }

                            $image_resolutions[] = [
                                "width" => $width,
                                "height" => $height,
                                "color_space" => $color_space,
                                "good_quality"  => $good_quality,
                                "good_image" => $good_image
                            ];
                        }
                    }
                }
                if ($contains_images) 
                {
                    if ($good_quality) {
                        $score += 1;
                    }
                    if ($good_image) {
                        $score += 1;
                    }
                    if($goodpdf != 1){
                        $score = 1;
                    }
                }else{
                    if($goodpdf != 0){
                        $score = 3;
                    }
                }

                if ($score >= 4) {
                    $qualityMessage = "Conclusion: PDF is of Good Quality!";
                } elseif ($score >= 2.5) {
                    $qualityMessage = "Conclusion: PDF is Acceptable, but some improvements are needed.";
                } else {
                    $qualityMessage = "Conclusion: PDF is Poor Quality! Consider regenerating it.";
                }

                echo json_encode([
                    "status_code" => 200,
                    "success" => true,
                    "message" => $message,
                    "amount" => $amount,
                    "score" => $score,
                    "qualityMessage" => $qualityMessage,
                    "contains_images" => $contains_images,
                    "image_resolutions" => $image_resolutions
                ]);
            }
		} else {
			echo json_encode([
				"status_code" => 400,
				"success" => false,
				"message" => "Upload valid pdf",
				"amount" => null,
				"contains_images" => null,
				"image_resolutions" => null
			]);
		}
    }

    public function image_check()
    {

        $count = 0;
        if (empty($_FILES['image']['name'])) {
            $count++;
            $message = "Image field is required.";
        }
        $allowed_types = array('image/jpg', 'image/jpeg', 'image/png');
        $file = $_FILES['image'];
        $file_path = $_FILES['image']['tmp_name'];
        $file_mime = mime_content_type($file['tmp_name']);
        $image_info = getimagesize($file['tmp_name']);
        $file_type = $_FILES['image']['type'];
        $file_size = $_FILES['image']['size'];
        $width = $image_info[0];
        $height = $image_info[1];
        $bit_depth = isset($image_info['bits']) ? $image_info['bits'] : "Unknown";
        $score = 0;

        if (!in_array($file_type, $allowed_types)) {
            $count++;
            $message .= " Only JPG, JPEG, and PNG files are allowed.";
        }

        if ($file_size > 2 * 1024 * 1024) {
            $count++;
            $message .= " The image file size should not exceed 2MB.";
        }

        if (!$image_info) {
            $count++;
            $message .= " The image file size should not exceed 2MB.";
        }
        if ($count > 0) {
            $response = array(
                'status_code' => 200,
                'status' => false,
                'error' => $message
            );
        } else {
            if ($file_size >= 500000) {
                $score = 1;
            } else {
                $score = 0;
            }

            if ($width >= 1920 && $height >= 1080) {
                $score += 1;
            } elseif ($width >= 1280 && $height >= 720) {
                $score += 0.5;
            } else {
                $score += 0;
            }

            $sharpness  = $this->get_image_sharpness($file_path);
            if ($sharpness < 10) {
                $score += 0;
            } else {
                $score += 1;
            }
            $jpeg_quality = $this->get_jpeg_quality_from_qt($file_path);

            switch ($jpeg_quality) {
                case ($jpeg_quality >= 100):
                    $score += 1.5;
                    break;
                case ($jpeg_quality >= 70):
                    $score += 1.25;
                    break;
                case ($jpeg_quality >= 50):
                    $score += 1;
                    break;
                case ($jpeg_quality >= 30):
                    $score += 0.5;
                    break;
                default:
                    $score += 0;
                    break;
            }
            if ($bit_depth >= 24) {
                $score += 1;
            } elseif ($bit_depth >= 16) {
                $score += 0.5;
            } else {
                $score += 0;
            }

            if ($score >= 4) {
                $qualityMessage = "Image is in Good Quality!";
            } elseif ($score >= 2.5) {
                $qualityMessage = "Image is Acceptable. Not a Bad Quality.";
            } else {
                $qualityMessage = "Image is of Bad Quality! Consider regenerating it ";
            }

            $response = [
                "status_code" => 200,
                "status" => true,
                "width" => $width,
                "height" => $height,
                "bit_depth" => $bit_depth,
                "file_size_kb" => round($file_size / 1024, 2),
                "mime_type" => $file_mime,
                "jpeg_quality" => $jpeg_quality ?? "N/A",
                "sharpness" => $sharpness,
                "final_quality_score" => $score,
                'quality_message' => $qualityMessage
            ];
        }
        echo json_encode($response);
    }

