    private function get_jpeg_quality_from_qt($file_path)
    {
        $file = fopen($file_path, 'rb');
        if (!$file) return "Cannot open file.";

        while (!feof($file)) {
            $byte = ord(fread($file, 1));

            if ($byte == 0xFF) {
                $marker = ord(fread($file, 1));

                if ($marker == 0xDB) {
                    fread($file, 2);
                    $qt_info = ord(fread($file, 1));
                    fclose($file);
                    return round((5000 / $qt_info) < 100 ? (5000 / $qt_info) : 100, 2);
                }
            }
        }

        fclose($file);
    }
     
    private function get_image_sharpness($image_path)
    {
        $img = @imagecreatefromjpeg($image_path);
        if (!$img) return "Invalid image.";
        $width = imagesx($img);
        $height = imagesy($img);
        $total_pixels = $width * $height;
        $sharpness = 0;

        for ($x = 1; $x < $width - 1; $x++) {
            for ($y = 1; $y < $height - 1; $y++) {
                $rgb1 = imagecolorat($img, $x, $y);
                $rgb2 = imagecolorat($img, $x + 1, $y);
                $sharpness += abs($rgb1 - $rgb2);
            }
        }

        imagedestroy($img);
        return round($sharpness / $total_pixels, 2);
    }

    public function action_taskstatus()
    {
        if ($this->input->is_ajax_request()) {
            $lead_id = $this->input->post('lead_id');
            $task_status = $this->input->post('task_status');
            // $action_id = $this->input->post('action_id');
            // $status_id = $this->input->post('status_id');

            if (!empty($lead_id) && !empty($task_status)) {
                $update_array = array(
                    'task_status' => $task_status
                );
                $update = $this->mcommon->common_edit('leads', $update_array, array('id' => $lead_id));
                if ($update) {
                    echo json_encode(array('status_code' => 200, 'message' => 'Task status updated successfully.'));
                } else {
                    echo json_encode(array('status_code' => 400, 'message' => 'Unable to update task status. Please try again.'));
                }
            } else {
                echo json_encode(array('status_code' => 400, 'message' => 'Invalid input data.'));
            }
        } else {
            redirect('login');
        }
    }

