    // Visa Processing task action submission
    public function action_visa_submit($lead_id)
    {
        if ($this->verify_min_level(1)) {
            $lead_parent_id = $this->input->post('lead_parent_id');
            $visa_status = $this->input->post('visa_status');
            $task_status = $this->input->post('task_status');
            $task_remarks = $this->input->post('task_remarks');
            $applicant = $this->input->post('applicant');
            $pre_approval_status = $this->input->post('pre_approval_status');
            
            // Validate and process the visa data
            if (empty($lead_parent_id) || empty($lead_id) || empty($visa_status)) {
                $this->session->set_flashdata('alert', 'danger');
                $this->session->set_flashdata('alert_message', 'Invalid input data.');
                return redirect('leads/lead/view/' . $lead_parent_id);
            }

            if($visa_status == 'noOption') {
                $log_insert_array = array('action_id' => 431, 'lead_id' => $lead_parent_id, 'action_on' => date('Y-m-d H:i:s'), 'remarks' => $close_remarks, 'action_by' => $this->auth_user_id, 'status_id' => 630);
                $insert_log = $this->mcommon->common_insert('lead_action_log', $log_insert_array);
                $update_lead_array = array('lead_status' => 630);
                $update_lead = $this->mcommon->common_edit('leads', $update_lead_array, array('id' => $lead_parent_id));
                $update_array = array(
                    'visa_status' => $visa_status,
                    'task_status' => $task_status,
                    'task_remarks' => $task_remarks,
                    'visa_applicant' => $applicant,
                    'pre_approval_status' => !empty($pre_approval_status) ? $pre_approval_status : null
                );
    
                $update = $this->mcommon->common_edit('leads', $update_array, array('id' => $lead_id));
            } else {

                if(isset($_FILES['attachments_lead']) && count($_FILES['attachments_lead']['name']) > 0){
                    $this->load->library('upload');
                    $this->load->library('zip');
    
                    $upload_path = 'uploads/leads/';
                    if (!is_dir($upload_path)) {
                        mkdir($upload_path, 0777, true);
                    }
    
                    $files = $_FILES['attachments_lead'];
                    $countfiles = count($files['name']);
                    $uploaded_files = [];
    
                    for ($i = 0; $i < $countfiles; $i++) {
                        if (!empty($files['name'][$i])) {
                            $_FILES['file']['name']     = $files['name'][$i];
                            $_FILES['file']['type']     = $files['type'][$i];
                            $_FILES['file']['tmp_name'] = $files['tmp_name'][$i];
                            $_FILES['file']['error']    = $files['error'][$i];
                            $_FILES['file']['size']     = $files['size'][$i];
    
                            $config['upload_path']   = $upload_path;
                            $config['allowed_types'] = 'jpg|jpeg|png|gif|pdf';
                            $config['max_size']      = '15000';
                            $config['file_name']     = pathinfo($files['name'][$i], PATHINFO_FILENAME) . '_' . time();
    
                            $this->upload->initialize($config);
    
                            if ($this->upload->do_upload('file')) {
                                $uploadData = $this->upload->data();
                                $filename = $uploadData['file_name'];
    
                                $uploaded_files[] = [
                                    'name' => $files['name'][$i],
                                    'path' => $upload_path . $filename
                                ];
                            }
                        }
                    }
    
                    // Insert uploaded files
                    if (count($uploaded_files) > 1) {
                        // Create ZIP file
                        $zip_filename = 'attachments_' . $lead_id . '_' . time() . '.zip';
                        $zip_path = $upload_path . $zip_filename;
    
                        foreach ($uploaded_files as $file) {
                            $this->zip->read_file($file['path']);
                        }
    
                        $this->zip->archive($zip_path);
    
                        $insert_attachment_array = [
                            'lead_id'         => $lead_id,
                            'attachment_name' => 'Multiple Attachments',
                            'attachment_url'  => base_url($zip_path)
                        ];
                        $this->mcommon->common_insert('lead_attachments', $insert_attachment_array);
    
                        // Optionally delete individual files
                        foreach ($uploaded_files as $file) {
                            unlink($file['path']);
                        }
                    } elseif (count($uploaded_files) === 1) {
                        $file = $uploaded_files[0];
                        $insert_attachment_array = [
                            'lead_id'         => $lead_id,
                            'attachment_name' => $file['name'],
                            'attachment_url'  => base_url($file['path'])
                        ];
                        $this->mcommon->common_insert('lead_attachments', $insert_attachment_array);
                    }
                }

                $update_array = array(
                    'visa_status' => $visa_status,
                    'task_status' => $task_status,
                    'task_remarks' => $task_remarks,
                    'visa_applicant' => $applicant,
                    'pre_approval_status' => !empty($pre_approval_status) ? $pre_approval_status : null
                );

                $lead_det = $this->leads_model->lead_details($lead_parent_id);
                $gc_message = array(
                    'customer_name' => $lead_det["customer_name"],
                );
                if($lead_det["is_corporate"] == 'Corporate'){
                    $gc_message['customer_name'] = $lead_det["applicant_name"];
                }

                if($visa_status == '3') { // 3 - in progress
                    $template = $applicant == 'depended'? 'gc_visa_depend_outside':'gc_visa_submitted';
                    $cc = [["name" => "GoldenCube", "email" => "team@goldencube.ae"]];
                        if($lead_det['is_corporate'] == 'Corporate'){
                            $cc = [["email"=>'Corporate@goldencube.ae']];
                        }
                    $email_array = array(
                        'email' => $lead_det["customer_email"],
                        'subject' => 'Visa application submitted',
                        'template' => 'mails/'.$template,
                        'from_name' => "Golden Cube",
                        'message' => $gc_message,
                        'branch_id' => '106',
                        'cc' => $cc,
                    );
                    // $send_mail = send_lead_template_email($email_array);
                    // $update_array['task_status'] = 'open';
                } else if ($visa_status == '4') { // Additional Doc. required
                    // $update_array['task_status'] = 'hold';
                } else if ($visa_status == '5') { // 5 - rejected
                $cc = [["name" => "GoldenCube", "email" => "team@goldencube.ae"]];
                        if($lead_det['is_corporate'] == 'Corporate'){
                            $cc = [["email"=>'Corporate@goldencube.ae']];
                        }
                    $email_array = array(
                        'email' => $lead_det["customer_email"],
                        'subject' => 'Visa application Rejected',
                        'template' => 'mails/gc_visa_rejected',
                        'from_name' => "Golden Cube",
                        'message' => $gc_message,
                        'branch_id' => '106',
                        'remarks' => $task_remarks,
                        'cc' => $cc,
                    );
                    $send_mail = send_lead_template_email($email_array);
                    // $update_array['task_status'] = 'completed';
                } else if ($visa_status == '6' && !empty($pre_approval_status) && ($pre_approval_status == 'medical' || $pre_approval_status == 'medical_outside')){ // 6 - pre approval
                    $template = $pre_approval_status == 'medical_outside'? 'gc_pre_approval_em_p': 'gc_pre_approval_m_p';
                    $attachment_insert = array();
                    if(isset($insert_attachment_array) && count($insert_attachment_array)){
                        $attachment = array(
                            'name'=>$insert_attachment_array['attachment_name'],
                            'filePath'=>$insert_attachment_array['attachment_url']
                        );
                        array_push($attachment_insert,$attachment);
                    }
                    $cc = [["name" => "GoldenCube", "email" => "team@goldencube.ae"]];
                        if($lead_det['is_corporate'] == 'Corporate'){
                            $cc = [["email"=>'Corporate@goldencube.ae']];
                        }
                    $email_array = array(
                        'email' => $lead_det["customer_email"],
                        'subject' => 'Visa Pre-Approval received',
                        'template' => 'mails/'.$template ,
                        'from_name' => "Golden Cube",
                        'message' => $gc_message,
                        'attachments' => $attachment_insert,
                        'remarks' => $task_remarks,
                        'branch_id' => '106',
                        'cc' => $cc,
                    );
                    $send_mail = send_lead_template_email($email_array);
                    // $update_array['task_status'] = 'hold';
                } else if ($visa_status == '7') { // 7 - Approved
                    $attachment_insert = array();
                    if(isset($insert_attachment_array) && count($insert_attachment_array)){
                        $attachment = array(
                            'name'=>$insert_attachment_array['attachment_name'],
                            'filePath'=>$insert_attachment_array['attachment_url']
                        );
                        array_push($attachment_insert,$attachment);
                    }
                    $cc = [["name" => "GoldenCube", "email" => "team@goldencube.ae"]];
                        if($lead_det['is_corporate'] == 'Corporate'){
                            $cc = [["email"=>'Corporate@goldencube.ae']];
                        }

                    $email_array = array(
                        'email' => $lead_det["customer_email"],
                        'subject' => 'Visa Approved',
                        'template' => 'mails/gc_visa_approved',
                        'from_name' => "Golden Cube",
                        'message' => $gc_message,
                        'attachments' => $attachment_insert,
                        'branch_id' => '106',
                        'remarks' => $task_remarks,
                        'cc' => $cc,
                    );
                    $send_mail = send_lead_template_email($email_array);
                    // $update_array['task_status'] = 'completed';
                } else if ($visa_status == '8') { // 8- No option
                    // $update_array['task_status'] = 'hold';
                }
    
                $update = $this->mcommon->common_edit('leads', $update_array, array('id' => $lead_id));
            }
            if ($update) {
                $this->session->set_flashdata('alert', 'success');
                $this->session->set_flashdata('alert_message', 'Task status - Visa processing updated successfully.');
            } else {
                $this->session->set_flashdata('alert', 'danger');
                $this->session->set_flashdata('alert_message', 'Unable to update task status - Visa processing. Please try again.');
            }
            return redirect('leads/lead/view/' . $lead_parent_id);

        } else {
            redirect('login');
        }
    }
