    // block and Unblock
    public function action_task_block($lead_id)
    {
        if ($this->verify_min_level(1)) {
            $lead_parent_id = $this->input->post('lead_parent_id');
            $task_status = $this->input->post('task_status');
            $block_category = $this->input->post('block_category');
            
            // Validate and process the visa data
            if (empty($lead_parent_id) || empty($lead_id) || empty($block_category)) {
                $this->session->set_flashdata('alert', 'danger');
                $this->session->set_flashdata('alert_message', 'Invalid input data.');
                return redirect('leads/lead/view/' . $lead_parent_id);
            }
            $lead_det = $this->leads_model->lead_details($lead_parent_id);
            $gc_message = array(
                'customer_name' => $lead_det["customer_name"],
            );
            if($lead_det["is_corporate"] == 'Corporate'){
                $gc_message['customer_name'] = $lead_det["applicant_name"];
            }

            if($task_status == 'hold' && $block_category == 'newProperty'){
                $close_remarks = "Task Block and Unblock -  Updated to hold with an Unblock property and provide new property";
                $log_insert_array = array('action_id' => 431, 'lead_id' => $lead_parent_id, 'action_on' => date('Y-m-d H:i:s'), 'remarks' => $close_remarks, 'action_by' => $this->auth_user_id, 'status_id' => 630);
                $insert_log = $this->mcommon->common_insert('lead_action_log', $log_insert_array);
                $update_lead_array = array('lead_status' => 630);
