                    return redirect('leads/lead/view/' . $lead_parent_id);
                }
                $log_insert_array = array('action_id' => 449, 'lead_id' => $lead_id, 'action_on' => date('Y-m-d H:i:s'), 'remarks' => 'The task for Block and Unblock (Sublead-'.$lead_id.') is completed.', 'action_by' => $this->auth_user_id, 'status_id' => 648);
                $insert_log = $this->mcommon->common_insert('lead_action_log', $log_insert_array);
                $update_array = array(
                    'block_category' => $block_category,
                    'task_status' => $task_status
                );

                $update = $this->mcommon->common_edit('leads', $update_array, array('id' => $lead_id));
                if($task_status == 'completed' && $block_category == 'newProperty'){
