    public function action_task_reopen($lead_id) {
        if ($this->verify_min_level(1)) {
            $lead_parent_id = $this->input->post('lead_parent_id');
            $reopen_remarks = $this->input->post('reopen_remarks');

             // Validate and process the data
            if (empty($lead_parent_id) || empty($reopen_remarks) || empty($lead_id)) {
                $this->session->set_flashdata('alert', 'danger');
                $this->session->set_flashdata('alert_message', 'Invalid input data.');
                return redirect('leads/lead/view/' . $lead_parent_id);
            }
            $user = $this->db->select("*")->from("users")->where("user_id", $this->auth_user_id)->get()->first_row();
            $user_name = $user->first_name . " " . $user->last_name;

            $remarks = 'Task Reopened for sub-lead-'.$lead_id.' by '.$user_name;

            $log_insert_array = array('action_id' => 447, 'lead_id' => $lead_parent_id, 'action_on' => date('Y-m-d H:i:s'), 'remarks' => $remarks, 'action_by' => $this->auth_user_id, 'status_id' => 646);
            $insert_log = $this->mcommon->common_insert('lead_action_log', $log_insert_array);

            $update_array = array(
                'task_status' => 'open',
                'task_remarks'=> $reopen_remarks
            );

            $update = $this->mcommon->common_edit('leads', $update_array, array('id' => $lead_id));
             if ($update) {
                $this->session->set_flashdata('alert', 'success');
                $this->session->set_flashdata('alert_message', 'Task for sub-lead-'.$lead_id.' is Reopened successfully.');
            } else {
                $this->session->set_flashdata('alert', 'danger');
                $this->session->set_flashdata('alert_message', 'Unable to update task status. Please try again.');
            }
            return redirect('leads/lead/view/' . $lead_parent_id);
        } else {
            redirect('login');
        }
    }

