                        if($lead_det['is_corporate'] == 'Corporate'){
                            $cc = [["email"=>'Corporate@goldencube.ae']];
                        }
    
                    $email_array = array(
                        'email' => $lead_det["customer_email"],
                        'subject' => 'Your Property Valuation Certificate is Ready',
                        'template' => 'mails/gc_valuation_complete',
                        'from_name' => "Golden Cube",
                        'message' => $gc_message,
                        'attachments' => $attachment_insert,
                        'branch_id' => '106',
                        'cc' => $cc,
                    );
                    $send_mail = send_lead_template_email($email_array);
                } else {
                    $this->session->set_flashdata('alert', 'danger');
                    $this->session->set_flashdata('alert_message', 'Unable to update task status. Please try after completing the sublead.');
                    return redirect('leads/lead/view/' . $lead_parent_id);
                }
            } else if($task_status == 'open'){
                $log_insert_array = array('action_id' => 447, 'lead_id' => $lead_id, 'action_on' => date('Y-m-d H:i:s'), 'remarks' => 'The task for '.$status.' (Sublead-'.$lead_id.') is open.', 'action_by' => $this->auth_user_id, 'status_id' => 646);
                $insert_log = $this->mcommon->common_insert('lead_action_log', $log_insert_array);
                $update_array = array(
                    'task_status' => $task_status
                );
                $update = $this->mcommon->common_edit('leads', $update_array, array('id' => $lead_id));
            }

            if ($update) {
                $this->session->set_flashdata('alert', 'success');
                $this->session->set_flashdata('alert_message', 'Task status - '.$status .' updated successfully.');
            } else {
                $this->session->set_flashdata('alert', 'danger');
                $this->session->set_flashdata('alert_message', 'Unable to update task status - '.$status .'. Please try again.');
            }
            return redirect('leads/lead/view/' . $lead_parent_id);

        } else {
            redirect('login');
        }
    }

