                        $this->session->set_flashdata('alert_message', 'Unable to send email at this moment.Please try again.');
                        redirect('leads/lead/view/' . $lead_parent_id);
                    }
                } else {
                    $this->session->set_flashdata('alert', 'danger');
                    if($ins_status == 'quotation_sent'){
                        $this->session->set_flashdata('alert_message', 'Unable to update task status. Quotation is already sent.');
                    } else if (empty($quotation_amount)) {
                        $this->session->set_flashdata('alert_message', 'Unable to update task status. Quotation Amount is Empty.');
                    }
                }
                redirect('leads/lead/view/' . $lead_parent_id);
            } else if($task_status == 'completed' && $ins_status == 'quotation_sent') {
                $lead_status = $this->mcommon->specific_row_value('leads', array('id' => $lead_id), 'lead_status');
                if($lead_status == 305) {
                    if(isset($_FILES['attachments_lead']) && count($_FILES['attachments_lead']['name']) > 0){
                        $this->load->library('upload');
                        $this->load->library('zip');
        
                        $upload_path = 'uploads/leads/';
                        if (!is_dir($upload_path)) {
                            mkdir($upload_path, 0777, true);
                        }
        
                        $files = $_FILES['attachments_lead'];
                        $countfiles = count($files['name']);
                        $uploaded_files = [];
        
                        for ($i = 0; $i < $countfiles; $i++) {
                            if (!empty($files['name'][$i])) {
                                $_FILES['file']['name']     = $files['name'][$i];
                                $_FILES['file']['type']     = $files['type'][$i];
                                $_FILES['file']['tmp_name'] = $files['tmp_name'][$i];
                                $_FILES['file']['error']    = $files['error'][$i];
                                $_FILES['file']['size']     = $files['size'][$i];
        
                                $config['upload_path']   = $upload_path;
                                $config['allowed_types'] = 'jpg|jpeg|png|gif|pdf';
                                $config['max_size']      = '15000';
                                $config['file_name']     = pathinfo($files['name'][$i], PATHINFO_FILENAME) . '_' . time();
        
                                $this->upload->initialize($config);
        
                                if ($this->upload->do_upload('file')) {
                                    $uploadData = $this->upload->data();
                                    $filename = $uploadData['file_name'];
        
                                    $uploaded_files[] = [
                                        'name' => $files['name'][$i],
                                        'path' => $upload_path . $filename
                                    ];
                                }
                            }
                        }

                        // Insert uploaded files
                        if (count($uploaded_files) > 1) {
                            // Create ZIP file
                            $zip_filename = 'attachments_' . $lead_id . '_' . time() . '.zip';
                            $zip_path = $upload_path . $zip_filename;
        
                            foreach ($uploaded_files as $file) {
                                $this->zip->read_file($file['path']);
                            }
        
                            $this->zip->archive($zip_path);
        
                            $insert_attachment_array = [
                                'lead_id'         => $lead_id,
                                'attachment_name' => 'Multiple Attachments',
                                'attachment_url'  => base_url($zip_path)
                            ];
                            $this->mcommon->common_insert('lead_attachments', $insert_attachment_array);
        
                            // Optionally delete individual files
                            foreach ($uploaded_files as $file) {
                                unlink($file['path']);
                            }
                        } elseif (count($uploaded_files) === 1) {
                            $file = $uploaded_files[0];
                            $insert_attachment_array = [
                                'lead_id'         => $lead_id,
                                'attachment_name' => $file['name'],
                                'attachment_url'  => base_url($file['path'])
                            ];
                            $this->mcommon->common_insert('lead_attachments', $insert_attachment_array);
                        }
                    }

                    $log_insert_array = array('action_id' => 449, 'lead_id' => $lead_parent_id, 'action_on' => date('Y-m-d H:i:s'), 'remarks' => 'The task for Attestation Process(Sublead-'.$lead_id.') is completed.', 'action_by' => $this->auth_user_id, 'status_id' => 648);
                    $insert_log = $this->mcommon->common_insert('lead_action_log', $log_insert_array);

                    $update_array = array(
                        'task_status' => $task_status,
                        'task_remarks' => $task_remarks
                    );

                    $lead_det = $this->leads_model->lead_details($lead_parent_id);
                    $gc_message = array(
                        'customer_name' => $lead_det["customer_name"],
                    );
                    if($lead_det["is_corporate"] == 'Corporate'){
                        $gc_message['customer_name'] = $lead_det["applicant_name"];
                    }
                    $attachment_insert = array();
                    if(isset($insert_attachment_array) && count($insert_attachment_array)){
                        $attachment = array(
                            'name'=>$insert_attachment_array['attachment_name'],
                            'filePath'=>$insert_attachment_array['attachment_url']
                        );
                        array_push($attachment_insert,$attachment);
                    }

                    $template = $document_type == 'digital' ? 'mails/gc_attest_digital_complete' : 'mails/gc_attest_phy_complete';
                    $subject = $document_type == 'digital' ? 'Attested Document Ready – Attached':'Attestation Completed - Document Ready for Collection';
                    $cc = [["name" => "GoldenCube", "email" => "team@goldencube.ae"]];
                        if($lead_det['is_corporate'] == 'Corporate'){
                            $cc = [["email"=>'Corporate@goldencube.ae']];
                        }

                    $email_array = array(
                        'email' => $lead_det["customer_email"],
                        'subject' => $subject,
                        'template' => $template,
                        'from_name' => "Golden Cube",
                        'message' => $gc_message,
                        'branch_id' => '106',
                        'cc' => $cc,
                        'remarks' => $task_remarks
                    );
                    if($document_type == 'digital'){
                        $email_array['attachments'] = $attachment_insert;
                    }
                    $send_mail = send_lead_template_email($email_array);

                    $update = $this->mcommon->common_edit('leads', $update_array, array('id' => $lead_id));
                    if ($update) {
                        $this->session->set_flashdata('alert', 'success');
                        $this->session->set_flashdata('alert_message', 'Task status - Attestation processing is updated successfully.');
                    } else {
                        $this->session->set_flashdata('alert', 'danger');
                        $this->session->set_flashdata('alert_message', 'Unable to update task status - Attestation processing. Please try again.');
                    }
                    return redirect('leads/lead/view/' . $lead_parent_id);
                } else {
                    $this->session->set_flashdata('alert', 'danger');
                    $this->session->set_flashdata('alert_message', 'Unable to update task status. Please try after completing the sublead.');
                    return redirect('leads/lead/view/' . $lead_parent_id);
                }
            } else if ($task_status == 'hold'){
                $log_insert_array = array('action_id' => 448, 'lead_id' => $lead_parent_id, 'action_on' => date('Y-m-d H:i:s'), 'remarks' => 'The task for Attestation Process (Sublead-'.$lead_id.') is hold.', 'action_by' => $this->auth_user_id, 'status_id' => 647);
                $insert_log = $this->mcommon->common_insert('lead_action_log', $log_insert_array);

                $update_array = array(
                    'task_status' => $task_status,
