            } else if ($task_status == 'hold'){
                $log_insert_array = array('action_id' => 448, 'lead_id' => $lead_parent_id, 'action_on' => date('Y-m-d H:i:s'), 'remarks' => 'The task for Translation Process (Sublead-'.$lead_id.') is hold.', 'action_by' => $this->auth_user_id, 'status_id' => 647);
