                $update = $this->mcommon->common_edit('leads', $update_array, array('id' => $lead_id));
                $update_lead_array = array('lead_status' => 630);
                $update_lead = $this->mcommon->common_edit('leads', $update_lead_array, array('id' => $lead_parent_id));
                if ($update) {
                    $this->session->set_flashdata('alert', 'success');
                    $this->session->set_flashdata('alert_message', 'Task status - Translation process is updated successfully.');
                } else {
                    $this->session->set_flashdata('alert', 'danger');
                    $this->session->set_flashdata('alert_message', 'Unable to update task status - Translation process. Please try again.');
                }
                return redirect('leads/lead/view/' . $lead_parent_id);
            } else {
                $this->session->set_flashdata('alert', 'danger');
                $this->session->set_flashdata('alert_message', 'Already the task is updated. Please try again with other status.');
                return redirect('leads/lead/view/' . $lead_parent_id);
            }
        } else {
            redirect('login');
        }
    }

