                        $action_message = '';
                        $log_insert_array = array('action_id' => 443, 'action_amount' => $amount_payment, 'lead_id' => $lead_id, 'action_on' => $current_timestamp, 'remarks' => '<pre>' . $action_message . '</pre>', 'action_by' => $this->auth_user_id, 'status_id' => 642, "bot_id" => $bot_id);
    
                        $insert_log = $this->mcommon->common_insert('lead_action_log', $log_insert_array);
    
                        $action_id = $this->db->insert_id();
                        $log_id = encrypt_decrypt($action_id);
                        if($payment_type == 'online'){
                            $payment_link = "https://crm.ontimegroup.com/payment/ccpay?ref=" . $token . "&token=" . $crypt_amount . "&identity=" . $log_id;
                            $this->mcommon->common_edit('lead_action_log', ["payment_link" => $payment_link], array('id' => $action_id));
                        }
                        $quotation_link = base_url() . "leads/lead/quotation?token=" . encrypt_decrypt(md5($lead_id)) . "&action=" . encrypt_decrypt($action_id);
    
                        // $this->mcommon->common_edit('lead_action_log', ["payment_link" => $payment_link, "gc_package_random_string" => $random_string, 'gc_package_id' => $package_id], array('id' => $action_id));
    
                        $payment_message = "<p></p><a href='" . $quotation_link . "'><button style='font-weight: bold;background: #00287c;color: white;border: 0;padding: 13px 30px;border-radius: 1px;box-shadow: 2px 2px 9px -2px black;'>View Quotation</button></a><p style='margin-top: 10px;margin-bottom: 30px;'>Note: Please use the above <b>View Quotation</b> button to see the quotation before " . date('Y-m-d H:i:s', strtotime(date('Y-m-d H:i:s') . '+48 hours')) . " to prevent from expire.</p><p></p>Sincerly,<br /><br />" . $agent_name . "<br />ONTIME GROUP";
    
                        $message .= $payment_message;
    
                        $OrderID = $action_id . "-OTLDPMET" . $lead_id;
    
                        $insert_log = $this->mcommon->common_edit('lead_action_log', ["remarks" => 'Quotation <b>#' . $OrderID . '</b> Created'], ["id" => $action_id]);
    
                        $update_lead_array = array('lead_status' => 642);
                        $update_lead = $this->mcommon->common_edit('leads', $update_lead_array, array('id' => $lead_id));
    
                        if ($customer_email != '') {
                            $cc = [["name" => "GoldenCube", "email" => "team@goldencube.ae"]];
                            if($is_corporate == 'Corporate'){
                                $cc = [["email"=>'Corporate@goldencube.ae']];
                            }
    
                            $email_array = array(
                                'email' => $customer_email,
                                'subject' => 'Golden Cube Quotation Request - '. $lead_id,
                                'template' => 'mails/lead_template',
                                'from_name' => $this->auth_first_name,
                                'from_email' => $this->auth_email,
                                'message' => $message,
                                'reply_to' => $this->auth_email,
                                'branch_id' => $branch_id,
                                'cc' => $cc,
                                // 'cc' => [["email"=>$this->auth_email]]
                            );
    
                            $send_mail = send_lead_template_email($email_array);
                            log_message('error', $send_mail);
    
                            //update lead status and contactable date in lead table
    
                            if ($send_mail) {
                                if ($insert_log > 0) {
                                    $this->session->set_flashdata('alert', 'success');
                                    $this->session->set_flashdata('alert_message', 'Quotation Generated successfully.');
                                } else {
                                    $this->session->set_flashdata('alert', 'danger');
                                    $this->session->set_flashdata('alert_message', 'Email sent successfully. But unable to update the lead record. Contact support.');
                                }
                            } else {
                                $this->session->set_flashdata('alert', 'danger');
                                $this->session->set_flashdata('alert_message', 'Unable to send email at this moment.Please try again.');
                            }
    
                            redirect(
                                'leads/lead/view/' . $lead_id
                            );
                        } else {
                            $this->session->set_flashdata('alert', 'danger');
                            $this->session->set_flashdata('alert_message', 'Unable to send email at this moment.Please try again.');
                            redirect('leads/lead/view/' . $lead_id);
                        }
                    } else {
                        $this->session->set_flashdata('alert', 'success');
                        $this->session->set_flashdata('alert_message', 'Selected Package have not sent Quotation automatically. Quotation will be sent after updating the Category.');
                        redirect('leads/lead/view/' . $lead_id);
                    }
                    // }
                }
            } else {
                $this->session->set_flashdata('alert', 'danger');
                $this->session->set_flashdata('alert_message', 'Unable to Create Quotation. Already have a Quotation for this lead.');
            }
        } else {
            redirect('login');
        }
    }

    
    public function ccmanage() {
        if ($this->verify_min_level(1)) {
            $category_array = $this->access_model->get_my_access_categories();
            
            if (!empty($category_array)) {
                $view_data['unassigned_leads'] = $this->leads_model->cc_contacts($category_array);
                $view_data['accepted_leads'] = $this->leads_model->cc_user_leads();
                $view_data['created_leads'] = $this->leads_model->cc_created_leads();
                if ($this->auth_user_role > 4) {
                    $view_data['reassigned_leads'] = $this->leads_model->cc_leads_reassigned();
                    $view_data['assigned_leads'] = $this->leads_model->cc_leads_assigned_by_coordinator();

                    if (isset($_POST['lead_type'])) {
                        $lead_type = $_POST['lead_type'];
                        $user_type = $_POST['user_type'];
                        if ($lead_type == "disqualified") {
                            $view_data['disqualified_leads'] = $this->leads_model->cc_disqualified_leads($user_type);
                            $view_data['converted_leads'] = $this->leads_model->cc_converted_leads();
                        }
                        if ($lead_type == "converted") {
                            $view_data['disqualified_leads'] = $this->leads_model->cc_disqualified_leads();
                            $view_data['converted_leads'] = $this->leads_model->cc_converted_leads($user_type);
                        }
                    } else {
                        $view_data['disqualified_leads'] = $this->leads_model->cc_disqualified_leads();
                        $view_data['converted_leads'] = $this->leads_model->cc_converted_leads();
                    }
                } else {
                    if (isset($_POST['lead_type'])) {
                        $lead_type = $_POST['lead_type'];
                        $user_type = $_POST['user_type'];
                        if ($lead_type == "disqualified") {
                            $view_data['disqualified_leads'] = $this->leads_model->cc_disqualified_leads($user_type);
                            $view_data['converted_leads'] = $this->leads_model->cc_converted_leads();
                        }
                        if ($lead_type == "converted") {
                            $view_data['disqualified_leads'] = $this->leads_model->cc_disqualified_leads();
                            $view_data['converted_leads'] = $this->leads_model->cc_converted_leads($user_type);
                        }
                    } else {
                        $view_data['converted_leads'] = $this->leads_model->cc_converted_leads();
                        $view_data['disqualified_leads'] = $this->leads_model->cc_disqualified_leads();
                    }
                }

            } else {
                $view_data['unassigned_leads'] = array();
                $view_data['accepted_leads'] = array();
                $view_data['converted_leads'] = array();
                $view_data['disqualified_leads'] = array();
            }

            $groups = $this->db->select('distinct(group_id)')->from("group_members")->where("user_id", $this->auth_user_id)->get()->result_array();
            $group_ids = [];
            foreach ($groups as $group) {
                array_push($group_ids, $group["group_id"]);
            }
            $view_data['group_ids'] = $group_ids;

            $data = array(
                'page_title' => 'Call Center Contacts',
                'title' => 'Call Center Contacts',
                'content' => $this->load->view('leads/lead/ccmanage', $view_data, true),
            );
            $this->load->view('template/base_template_modal_v2', $data);
        } else {
            redirect('login');
        }
    }

}